style.css:
@-moz-document domain("console.tomticket.com") {
/* 1. Fundo Geral e Reset de Cores */
    body, html, app-root, .main-content, .container-fluid {
        background-color: #121212 !important;
        color: #e0e0e0 !important;
    }

    /* 2. Cabeçalho Superior e Barra de Pesquisa */
    header, .topbar, .navbar, .header {
        background-color: #1e1e1e !important;
        border-bottom: 1px solid #333 !important;
    }

    input[type="text"], input[type="search"], .search-bar {
        background-color: #2d2d2d !important;
        color: #fff !important;
        border: 1px solid #444 !important;
        border-radius: 8px !important;
    }

    /* 3. Área Branca do Painel (Cards/Wrappers) */
    .card, .panel, .box, .content-wrapper, .bg-white {
        background-color: #1e1e1e !important;
        border: 1px solid #333 !important;
        box-shadow: none !important;
        color: #e0e0e0 !important;
    }

    /* 4. Estilização da Tabela de Chamados */
    table, .table {
        background-color: #1e1e1e !important;
        color: #e0e0e0 !important;
        border-collapse: collapse !important;
        width: 100% !important;
    }

    th, thead, .table-header {
        background-color: #2a2a2a !important;
        color: #a981ff !important;
        border-bottom: 2px solid #444 !important;
        padding: 12px !important;
    }

    td, tr {
        border-bottom: 1px solid #333 !important;
        background-color: transparent !important;
        padding: 10px !important;
    }

    tr:hover td, .table-hover tbody tr:hover {
        background-color: #2a2a2a !important;
        cursor: pointer;
    }

    .text-muted, span[style*="color"] {
        color: #aaaaaa !important;
    }

    /* 5. Correção do Menu "Novo Chamado" (Menu Quebrado) */
    .dropdown-menu, .mat-menu-panel, .cdk-overlay-pane, ul.dropdown {
        position: absolute !important;
        z-index: 99999 !important;
        background-color: #252525 !important;
        border: 1px solid #444 !important;
        border-radius: 8px !important;
        box-shadow: 0px 8px 16px rgba(0,0,0,0.6) !important;
    }

    .dropdown-item, .mat-menu-item, li.menu-item {
        color: #e0e0e0 !important;
        background-color: transparent !important;
    }

    .dropdown-item:hover, .mat-menu-item:hover {
        background-color: #a981ff !important;
        color: #fff !important;
    }

    /* 6. Abas Superiores */
    .nav-tabs, .tabs {
        border-bottom: 1px solid #444 !important;
    }

    .nav-tabs > li > a, .tab-link {
        color: #aaa !important;
        background-color: transparent !important;
    }

    .nav-tabs > li.active > a, .tab-link.active {
        color: #a981ff !important;
        background-color: #2a2a2a !important;
        border-color: #444 #444 transparent !important;
    }

    /* 7. Badges */
    .badge, .label {
        background-color: #ff4b4b !important;
        color: #fff !important;
        border-radius: 12px !important;
    }
}
